CREATE TYPE "Role" AS ENUM ('USER','ADMIN');
CREATE TYPE "Status" AS ENUM ('OPEN','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TYPE "Priority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"password" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'USER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Ticket" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"priority" "Priority" NOT NULL DEFAULT 'MEDIUM',"status" "Status" NOT NULL DEFAULT 'OPEN',"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Comment" ("id" TEXT PRIMARY KEY,"content" TEXT NOT NULL,"ticketId" TEXT NOT NULL REFERENCES "Ticket"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ActivityLog" ("id" TEXT PRIMARY KEY,"ticketId" TEXT NOT NULL REFERENCES "Ticket"("id") ON DELETE CASCADE,"userId" TEXT,"action" TEXT NOT NULL,"details" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"ticketId" TEXT NOT NULL REFERENCES "Ticket"("id") ON DELETE CASCADE,"message" TEXT NOT NULL,"type" TEXT NOT NULL,"isRead" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Ticket_userId_idx" ON "Ticket"("userId"); CREATE INDEX "Ticket_status_idx" ON "Ticket"("status"); CREATE INDEX "Ticket_priority_idx" ON "Ticket"("priority"); CREATE INDEX "Ticket_createdAt_idx" ON "Ticket"("createdAt"); CREATE INDEX "Comment_ticketId_createdAt_idx" ON "Comment"("ticketId","createdAt"); CREATE INDEX "ActivityLog_ticketId_createdAt_idx" ON "ActivityLog"("ticketId","createdAt"); CREATE INDEX "Notification_userId_createdAt_idx" ON "Notification"("userId","createdAt");
